class ClassName {
public:
    ReturnType operator()(ParameterTypes...);
};

// Usage:
ClassName obj;
obj(args...);

code_example:
#include <iostream>
#include <vector>
#include <algorithm>

class Multiplier {
public:
    explicit Multiplier(int factor) : factor_(factor) {}
    int operator()(int value) const {
        return value * factor_;
    }
private:
    int factor_;
};

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    Multiplier times_two(2);
    std::transform(numbers.begin(), numbers.end(), numbers.begin(), times_two);
    for (int n : numbers) {
        std::cout << n << ' ';
    }
    return 0;
}
